select periode,tiers,agence,categ,proj,sum(remise_except) remise_except from ( select a.invdat_0 periode,a.bpcinv_0 tiers,decode(substr(a.bpcinv_0,1,1),'X','C','Y','C','Z','C',substr(a.bpcinv_0,1,1)) agence,substr(a.bpcinv_0,2,1) categ, sum(b.dtanot_0)*-1 remise_except ,decode(substr(a.num_0,1,1),'F','N','P','P',decode(substr(a.num_0,1,2),'AP','P','AV','P')) proj from sinvoicev a, svcrfoot b where  a.num_0=b.vcrnum_0 and a.invdat_0 between '01/01/2016' and  '31/12/2026' and  a.invdtaamt_1 <> 0 and a.sivtyp_0 in ('FAC','FCP') group by a.invdat_0 ,a.bpcinv_0 ,decode(substr(a.bpcinv_0,1,1),'X','C','Y','C','Z','C',substr(a.bpcinv_0,1,1)) ,substr(a.bpcinv_0,2,1),decode(substr(a.num_0,1,1),'F','N','P','P',decode(substr(a.num_0,1,2),'AP','P','AV','P'))  union  select a.invdat_0 periode,a.bpcinv_0 tiers,decode(substr(a.bpcinv_0,1,1),'X','C','Y','C','Z','C',substr(a.bpcinv_0,1,1)) agence,substr(a.bpcinv_0,2,1) categ, sum(b.dtanot_0) remise_except , decode(substr(a.num_0,1,1),'F','N','P','P',decode(substr(a.num_0,1,2),'AP','P','AV','P')) proj  from sinvoicev a, svcrfoot b where  a.num_0=b.vcrnum_0 and a.invdat_0 between '01/01/2016' and  '31/12/2026' and  a.invdtaamt_1 <> 0 and a.sivtyp_0 in ('AVO','AVP')  group by a.invdat_0 ,a.bpcinv_0 ,decode(substr(a.bpcinv_0,1,1),'X','C','Y','C','Z','C',substr(a.bpcinv_0,1,1)) ,substr(a.bpcinv_0,2,1) , decode(substr(a.num_0,1,1),'F','N','P','P',decode(substr(a.num_0,1,2),'AP','P','AV','P'))  ) group by periode,tiers,agence,categ,proj 
